/*! xhtml v1.1.0 - Unlicensed - inspired by htmx */

const xhtml = (() => {
  const methods = ["get", "post", "put", "patch", "delete"];

  const resolve = (node, selector) => {
    if(selector == "@self") return node;
    if(selector == "@document") return document.documentElement;

    const found = document.querySelector(selector);
    if(!found) throw new Error(`xhtml: nothing matches '${selector}'`);
    return found;
  };

  const collect = (source) => {
    if(source instanceof HTMLFormElement) return new FormData(source);

    const data = new FormData();
    if(source.matches("input, select, textarea")) data.append(source.name, source.value);
    else for(const [key, value] of Object.entries(source.dataset)) data.append(key, value);
    return data;
  };

  const merge = (url, data) => {
    const merged = new URL(url, location.href);

    for(const key of new Set(data.keys()))
      if(!merged.searchParams.has(key))
        for(const value of data.getAll(key)) merged.searchParams.append(key, value);

    return merged;
  };

  // When inserting scripts via innerHTML or outerHTML, the scripts do
  // not automatically get executed. The following loop recreates the
  // current script element or any child script elements. By reinserting
  // them in the DOM via appendChild, the JavaScript *does* get executed.
  
  // Please note that this can lead to 'redeclaration' errors if global
  // variables are created. This can be circumvented by using an IIFE or
  // by setting type="module" on the script element.

  const revive_scripts = (root) => {
    for(const dead of root.querySelectorAll("script")) {
      const script = document.createElement("script");
      for(const attr of dead.attributes) script.setAttribute(attr.name, attr.value);
      script.textContent = dead.textContent;
      dead.replaceWith(script);
    }
  };

  // If an element has autofocus, and no input element has currently
  // been focused, focus the element.

  const autofocus = (root) => {
    const interactive = "input, textarea, select, button, a[href], [contenteditable], [tabindex]";
    if(document.activeElement?.matches(interactive)) return;
    root.querySelector?.("[autofocus]")?.focus();
  };

  const swap = (target, html, replace = "innerHTML") => {
    let root = target;

    if(replace == "innerHTML") {
      target.innerHTML = html;
    }
    else {
      const template = document.createElement("template");
      template.innerHTML = html;
      root = template.content.firstElementChild;
      target.replaceWith(template.content);
    }

    if(!root) return;

    revive_scripts(root);
    autofocus(root);

    // Dispatch event for other scripts to optionally hook into.
    root.dispatchEvent(new CustomEvent("x-swap", { bubbles: true }));
  };

  const refresh = (selector) =>
    Promise.all([...document.querySelectorAll(selector)].map(node => node.x_run?.()));

  const exchange = async (node) => {
    const method = methods.find(m => node.hasAttribute(`x-${m}`));

    if(method) {
      const question = node.getAttribute("x-confirm");
      if(question && !confirm(question)) return;

      const target = resolve(node, node.getAttribute("x-target") || "@self");
      const data = collect(resolve(node, node.getAttribute("x-data") || "@self"));

      let url = node.getAttribute(`x-${method}`);
      const request = { method, headers: { Accept: "text/html" } };

      if(method == "get" || method == "delete") url = merge(url, data);
      else request.body = new URLSearchParams(data);

      target.setAttribute("x-loading", "");
      const response = await fetch(url, request);
      target.removeAttribute("x-loading");

      // On 'Moved Permanently', 'Found', 'See Other',
      // 'Temporary Redirect', 'Permanent Redirect', redirect the
      // caller to the target page indicated by the 'Location' header.
      if(response.redirected || [301, 302, 303, 307, 308].includes(response.status)) {
        location.href = response.headers.get("Location") || response.url;
        return;
      }

      // On 'No Content' or 'Not Modified' responses, do nothing, as
      // prescribed by the HTTP specification.
      if(![204, 304].includes(response.status)) {
        swap(target, await response.text(), node.getAttribute("x-replace") || "innerHTML");
      }
    }

    const targets = node.getAttribute("x-refresh");
    if(targets) await refresh(targets);
  };

  const default_event = (node) => {
    if(node instanceof HTMLFormElement) return "submit";
    if(node.matches("button, a, input[type=button], input[type=submit]")) return "click";
    if(node.matches("input, select, textarea")) return "change";
    return "load";
  };

  const selector = [...methods.map(m => `[x-${m}]`), "[x-refresh]"].join(", ");

  const bind = (node) => {
    if(node.x_run) return;
    node.x_run = () => exchange(node);

    const event = node.getAttribute("x-on") || default_event(node);

    // Enter inside a form submits it natively; swallow that when the form
    // triggers on some other event.
    if(node instanceof HTMLFormElement && event != "submit")
      node.addEventListener("submit", (e) => e.preventDefault());

    if(event == "load") node.x_run();
    else node.addEventListener(event, (e) => {
      e.preventDefault();
      node.x_run();
      if(e.target instanceof HTMLFormElement) e.target.reset();
    });
  };

  const hydrate = (root) => {
    if(root.matches?.(selector)) bind(root);
    root.querySelectorAll?.(selector).forEach(bind);
  };

  addEventListener("DOMContentLoaded", () => {
    hydrate(document.body);

    // Observed on the root, which no swap ever replaces (@document swaps the
    // body out from under anything watching it).
    new MutationObserver((mutations) => {
      for(const mutation of mutations)
        for(const node of mutation.addedNodes)
          if(node.nodeType == 1) hydrate(node);
    }).observe(document.documentElement, { childList: true, subtree: true });
  });

  return { hydrate, refresh, swap };
})();
